sql-set.sql:
				INSERT INTO "AcmeProduct" (
    "Code",
    "SKU",
    "Name",
    "DisplayName",
    "ShortName",
    "Description",
    "ProductType",
    "BaseCost",
    "BasePrice",
    "Currency",
	"ProductOwnerId",
    "ProductOwner",
    "ProductCode",
    "ProductActive",
    "SalesStartDate",
    "SalesEndDate",
    "SupportStartDate",
    "SupportEndDate",
	"VendorId",
    "VendorName",
    "ProductCategoryId",
    "ProductCategory",
    "ManufacturerId",
    "Manufacturer",
    "UnitPrice",
    "CommissionRate",
    "TaxId",
    "Tax",
    "UsageUnitId",
    "UsageUnit",
    "QuantityInStock",
    "HandlerId",
    "Handler",
    "QuantityOrdered",
    "ReorderLevel",
    "QuantityInDemand",
    "CreatedBy",
    "CreatedDateTime",
    "UpdatedDateTime",
    "IsActive",
    "IsDeleted",
	"CustomFields"
)
VALUES (
    @Code,
    @SKU,
    @Name,
    @DisplayName,
    @ShortName,
    @Description,
    @ProductType,
    @BaseCost,
    @BasePrice,
    @Currency,
    @ProductOwnerId,
	@ProductOwner,
    @ProductCode,
    @ProductActive,
    @SalesStartDate,
    @SalesEndDate,
    @SupportStartDate,
    @SupportEndDate,
	@VendorId,
	@VendorName,
    @ProductCategoryId,
    @ProductCategory,
    @ManufacturerId,
    @Manufacturer,
    @UnitPrice,
    @CommissionRate,
    @TaxId,
    @Tax,
    @UsageUnitId,
    @UsageUnit,
    @QuantityInStock,
    @HandlerId,
    @Handler,
    @QuantityOrdered,
    @ReorderLevel,
    @QuantityInDemand,
    @CreatedBy,
    @CreatedDateTime,
    @UpdatedDateTime,
    TRUE,
    FALSE,
	@CustomFields
)
RETURNING "Id";
